def closestPairSum(nums, target):
    lo, hi = 0, len(nums) - 1
    best = None
    while lo < hi:
        s = nums[lo] + nums[hi]
        key = (abs(s - target), s)
        if best is None or key < best:
            best = key
        if s == target:
            break
        if s < target:
            lo += 1
        else:
            hi -= 1
    return best[1]
